import java.io.IOException;
import java.nio.file.*;
import java.text.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Bundel.siapkan("label",
                "", "simpan=Save\nhapus=Delete\n",
                "_id", "simpan=Simpan\nhapus=Hapus\n");
        Scanner in = new Scanner(System.in);
        Locale locale = Locale.forLanguageTag(in.nextLine().trim());
        ResourceBundle rb = ResourceBundle.getBundle("label", locale);
        while (in.hasNextLine()) {
            String kunci = in.nextLine().trim();
            String teks = rb.containsKey(kunci) ? rb.getString(kunci) : "??" + kunci + "??";
            System.out.println(kunci + " = " + teks);
        }
    }
}

class Bundel {
    // Khusus editor: menulis file .properties ke folder kerja, yang ada di classpath.
